// РОЗВІДКА №2: повні URL і тіла помилок при вході. ЖОДНИХ ЗАПИСІВ.
const { chromium } = require('playwright');
const fs = require('fs');
(async () => {
  const env = {};
  for (const l of fs.readFileSync('/root/unitex-finrep/secure/odata_write.env','utf8').split('\n')) {
    const m = l.match(/^\s*([A-Z_]+)\s*=\s*(.+?)\s*$/); if (m) env[m[1]] = m[2];
  }
  const browser = await chromium.launch({ args:['--no-sandbox','--ignore-certificate-errors'] });
  const ctx = await browser.newContext({ ignoreHTTPSErrors:true, viewport:{width:1400,height:900}, locale:'uk-UA' });
  const page = await ctx.newPage();
  const bad = [];
  page.on('response', async r => {
    if (r.status() >= 400) {
      let body = '';
      try { body = (await r.text()).replace(/\s+/g,' ').slice(0,500); } catch(e) { body = '(тіло не прочиталось)'; }
      bad.push({ st:r.status(), url:r.url(), body });
    }
  });
  page.on('dialog', d => d.accept());
  await page.goto('https://unitex.rdport.net:29231/DB/', { waitUntil:'load', timeout:60000 });
  await page.waitForTimeout(7000);
  await page.fill('#userName', env.ODATA_USER);
  await page.fill('#userPassword', env.ODATA_PASS);
  await page.press('#userPassword','Enter');
  await page.waitForTimeout(25000);
  console.log('ФІНАЛЬНИЙ URL:', page.url());
  for (const b of bad) {
    console.log('---');
    console.log('HTTP', b.st);
    console.log('URL :', b.url);
    console.log('ТІЛО:', b.body || '(порожнє)');
  }
  if (!bad.length) console.log('помилок HTTP немає');
  await browser.close();
})().catch(e => { console.log('ПОМИЛКА:', String(e).slice(0,300)); process.exit(1); });
EOJS
cd /root/webbot && timeout 200 node diag2.js 2>&1 | tail -40
